                    .background(StatusEmergencyContent)
            )
            Text(
                text = "Emergency",
                style = MaterialTheme.typography.labelSmall.copy(
                    fontWeight = FontWeight.Bold,
                    letterSpacing = 0.3.sp
                ),
                color = StatusEmergencyContent
            )
        }
    }
}

/** Tappable emergency toggle chip for forms. */
@Composable
fun EmergencyToggleChip(isEmergency: Boolean, onToggle: () -> Unit) {
    val redTint = Color(0xFFD32F2F)
    Surface(
        onClick = onToggle,
        shape   = RoundedCornerShape(50),
        color   = if (isEmergency) StatusEmergencyBg else Color.Transparent,
        border  = if (isEmergency) null
                  else BorderStroke(1.dp, redTint.copy(alpha = 0.5f))
    ) {
        Row(
            modifier = Modifier.padding(horizontal = 10.dp, vertical = 6.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(6.dp)
        ) {
            Icon(
                imageVector = Icons.Filled.Warning,
                contentDescription = null,
                modifier = Modifier.size(14.dp),
                tint = if (isEmergency) StatusEmergencyContent else redTint
            )
            Text(
                text = if (isEmergency) "Emergency" else "Mark Emergency",
                fontWeight = if (isEmergency) FontWeight.Bold else FontWeight.Medium,
                fontSize = 11.sp,
                color = if (isEmergency) StatusEmergencyContent else redTint
            )
            if (isEmergency) {
                Icon(
                    Icons.Filled.Close,
                    contentDescription = "Remove emergency",
                    modifier = Modifier.size(12.dp),
                    tint = StatusEmergencyContent.copy(alpha = 0.8f)
                )
            }
        }
    }
}

// ══════════════════════════════════════════════════════════════════════════════
// ── REQUEST LIST SCREEN
// ══════════════════════════════════════════════════════════════════════════════

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RequestListScreen(
    requests: List<RequestEntity>,
    emergencyIds: Set<Int> = emptySet(),
    onAddClick: () -> Unit,
    onItemClick: (RequestEntity) -> Unit,
    bottomBar: @Composable () -> Unit = {}
) {
    var searchQuery  by remember { mutableStateOf("") }
    var activeFilter by remember { mutableStateOf(FilterTag.ALL) }

    val todayStart = remember {
        Calendar.getInstance().apply {
            set(Calendar.HOUR_OF_DAY, 0); set(Calendar.MINUTE, 0)
            set(Calendar.SECOND, 0);      set(Calendar.MILLISECOND, 0)
        }.timeInMillis
    }

    val pendingCount   = remember(requests) { requests.count { it.status == RequestStatus.PENDING } }
    val deliveredCount = remember(requests) { requests.count { it.status == RequestStatus.DELIVERED } }
    val todayCount     = remember(requests) { requests.count { it.createdAt >= todayStart } }

    val filteredRequests = remember(requests, searchQuery, activeFilter) {
        requests.filter { req ->
            val q = searchQuery.trim().lowercase()
            val matchesSearch = q.isBlank() ||
                    req.customerName.lowercase().contains(q) ||
                    req.phoneNumber.contains(q)
            val matchesTag = when (activeFilter) {
                FilterTag.ALL       -> true
                FilterTag.TODAY     -> req.createdAt >= todayStart
                FilterTag.PENDING   -> req.status == RequestStatus.PENDING
                FilterTag.DELIVERED -> req.status == RequestStatus.DELIVERED
            }
            matchesSearch && matchesTag
        }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = {
                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                        Box(
                            contentAlignment = Alignment.Center,
                            modifier = Modifier
                                .size(34.dp)
                                .clip(RoundedCornerShape(10.dp))
                                .background(MaterialTheme.colorScheme.onPrimary.copy(alpha = 0.15f))
                        ) {
                            Text("", fontSize = 16.sp)
                        }
                        Column {
                            Text("MedQueue", fontWeight = FontWeight.Bold, fontSize = 17.sp)
                            Text(
                                "Medicine requests",
                                style = MaterialTheme.typography.labelSmall,
                                color = TopBarContent.copy(alpha = 0.65f)
                            )
                        }
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor    = TopBarContainer,
                    titleContentColor = TopBarContent
                )
            )
        },
        bottomBar = bottomBar,
        floatingActionButton = {
            ExtendedFloatingActionButton(
                onClick        = onAddClick,
                icon           = { Icon(Icons.Filled.Add, contentDescription = null) },
                text           = { Text("New Request", fontWeight = FontWeight.SemiBold) },
                containerColor = MaterialTheme.colorScheme.primary,
                contentColor   = MaterialTheme.colorScheme.onPrimary,
                shape          = RoundedCornerShape(16.dp)
            )
        },
        containerColor = MaterialTheme.colorScheme.background
    ) { padding ->
        Column(modifier = Modifier.padding(padding)) {

            // ── Stats bar ──────────────────────────────────────────────────
            if (requests.isNotEmpty()) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .background(MaterialTheme.colorScheme.surface)
                        .padding(horizontal = 16.dp, vertical = 10.dp),
                    horizontalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    StatChip(label = "Total",     value = requests.size.toString(),  modifier = Modifier.weight(1f))
                    StatChip(label = "Pending",   value = pendingCount.toString(),   color = StatusPendingContent,   bg = StatusPendingBg.copy(alpha = 0.7f),   modifier = Modifier.weight(1f))
                    StatChip(label = "Delivered", value = deliveredCount.toString(), color = StatusDeliveredContent, bg = StatusDeliveredBg.copy(alpha = 0.7f), modifier = Modifier.weight(1f))
                    StatChip(label = "Today",     value = todayCount.toString(),     modifier = Modifier.weight(1f))
                }
                HorizontalDivider(thickness = 0.5.dp, color = MaterialTheme.colorScheme.outlineVariant)
            }

            // ── Search bar ─────────────────────────────────────────────────
            OutlinedTextField(
                value         = searchQuery,
                onValueChange = { searchQuery = it },
                placeholder   = { Text("Search by name or phone…", color = MaterialTheme.colorScheme.outline) },
                leadingIcon   = {
                    Icon(Icons.Filled.Search, "Search",
                        tint = MaterialTheme.colorScheme.onSurfaceVariant,
                        modifier = Modifier.size(20.dp))
                },
                trailingIcon  = {
                    if (searchQuery.isNotEmpty()) {
                        IconButton(onClick = { searchQuery = "" }) {
                            Icon(Icons.Filled.Close, "Clear", modifier = Modifier.size(18.dp))
                        }
                    }
                },
                singleLine = true,
                shape      = RoundedCornerShape(14.dp),
                modifier   = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp, vertical = 10.dp)
            )

            // ── Filter chips ───────────────────────────────────────────────
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp)
                    .padding(bottom = 8.dp),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                FilterTag.entries.forEach { tag ->
                    FilterChip(
                        selected = activeFilter == tag,
                        onClick  = { activeFilter = tag },
                        label    = {
                            Text(
                                tag.label,
                                fontWeight = if (activeFilter == tag) FontWeight.SemiBold else FontWeight.Normal,
                                fontSize   = 13.sp
                            )
                        },
                        shape  = RoundedCornerShape(50),
                        colors = FilterChipDefaults.filterChipColors(
                            selectedContainerColor = MaterialTheme.colorScheme.primary,
                            selectedLabelColor     = MaterialTheme.colorScheme.onPrimary
                        )
                    )
                }
            }

            // ── List / empty state ─────────────────────────────────────────
            if (filteredRequests.isEmpty()) {
                EmptyState(
                    hasRequests = requests.isNotEmpty(),
                    modifier    = Modifier.fillMaxSize()
                )
            } else {
                LazyColumn(
                    contentPadding      = PaddingValues(horizontal = 16.dp, vertical = 4.dp),
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    items(filteredRequests, key = { it.id }) { request ->
                        RequestListItem(
                            request     = request,
                            isEmergency = request.id in emergencyIds,
                            onClick     = { onItemClick(request) }
                        )
                    }
                    item { Spacer(modifier = Modifier.height(80.dp)) }
                }
            }
        }
    }
}

// ── Mini stat chip used in the stats bar ─────────────────────────────────────

@Composable
private fun StatChip(
    label    : String,
    value    : String,
    modifier : Modifier = Modifier,
    color    : Color    = MaterialTheme.colorScheme.onSurface,
    bg       : Color    = MaterialTheme.colorScheme.surfaceVariant
) {
    Surface(
        modifier = modifier,
        shape    = RoundedCornerShape(10.dp),
        color    = bg
    ) {
        Column(
            modifier            = Modifier.padding(vertical = 8.dp, horizontal = 4.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Text(value, fontWeight = FontWeight.Bold, fontSize = 16.sp, color = color)
            Text(label, fontSize = 10.sp, color = color.copy(alpha = 0.75f), letterSpacing = 0.2.sp)
        }
    }
}

// ── Empty state illustration ──────────────────────────────────────────────────

@Composable
private fun EmptyState(hasRequests: Boolean, modifier: Modifier = Modifier) {
    Box(modifier = modifier, contentAlignment = Alignment.Center) {
        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(8.dp),
            modifier = Modifier.padding(40.dp)
        ) {
            Box(
                contentAlignment = Alignment.Center,
                modifier = Modifier
                    .size(72.dp)
                    .clip(CircleShape)
                    .background(MaterialTheme.colorScheme.surfaceVariant)
            ) {
                Text(if (hasRequests) "" else "", fontSize = 30.sp)
            }
            Spacer(Modifier.height(4.dp))
            Text(
                text  = if (hasRequests) "No matches found" else "No requests yet",
                style = MaterialTheme.typography.titleMedium.copy(fontWeight = FontWeight.SemiBold),
                color = MaterialTheme.colorScheme.onSurface
            )
            Text(
                text      = if (hasRequests) "Try a different search or filter" else "Tap New Request to get started",
                style     = MaterialTheme.typography.bodySmall,
                color     = MaterialTheme.colorScheme.outline,
                textAlign = TextAlign.Center
            )
        }
    }
}

// ── Request list card ─────────────────────────────────────────────────────────

@Composable
fun RequestListItem(request: RequestEntity, isEmergency: Boolean = false, onClick: () -> Unit) {
    val dateFormat  = remember { SimpleDateFormat("dd MMM, hh:mm a", Locale.getDefault()) }
    val displayName = request.customerName.ifBlank { "Unknown" }
    val isPending   = request.status == RequestStatus.PENDING
    val cardBg      = if (isEmergency) CardEmergencyBg else if (isPending) CardPendingBg else CardDeliveredBg
    val stripeColor = if (isEmergency) StripeEmergency else if (isPending) StripePending  else StripeDelivered

    val medicineLines = remember(request.medicineName) {
        request.medicineName.lines().filter { it.isNotBlank() }
    }

    Card(
        modifier  = Modifier
            .fillMaxWidth()
            .clickable(onClick = onClick),
        shape     = RoundedCornerShape(16.dp),
        colors    = CardDefaults.cardColors(containerColor = cardBg),
        elevation = CardDefaults.cardElevation(defaultElevation = 1.dp)
    ) {
        Row(modifier = Modifier.fillMaxWidth().height(IntrinsicSize.Min)) {

            // Left accent stripe
            Box(
                modifier = Modifier
                    .width(5.dp)
                    .fillMaxHeight()
                    .background(
                        stripeColor,
                        RoundedCornerShape(topStart = 16.dp, bottomStart = 16.dp)
                    )
            )

            // Content
            Row(
                modifier = Modifier
                    .weight(1f)
                    .padding(start = 14.dp, end = 14.dp, top = 14.dp, bottom = 14.dp),
                horizontalArrangement = Arrangement.spacedBy(12.dp),
                verticalAlignment     = Alignment.Top
            ) {
                // Avatar
                InitialsAvatar(name = displayName, size = 42)

                // Text content
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(4.dp)) {

                    // Row: Name + badges
                    Row(
                        modifier              = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment     = Alignment.CenterVertically
                    ) {
                        Text(
                            text     = displayName,
                            style    = MaterialTheme.typography.titleSmall.copy(fontWeight = FontWeight.Bold),
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                            modifier = Modifier.weight(1f, fill = false)
                        )
                        Spacer(Modifier.width(8.dp))
                        Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                            if (isEmergency) EmergencyBadge()
                            StatusBadge(status = request.status)
                        }
                    }

                    // Phone
                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(5.dp)) {
                        Icon(
                            Icons.Filled.Phone,
                            contentDescription = null,
                            modifier = Modifier.size(13.dp),
                            tint     = MaterialTheme.colorScheme.outline
                        )
                        Text(
                            text  = "+91 ${request.phoneNumber}",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }

                    // Medicine pill-list (first 2 lines + overflow count)
                    val visibleMeds = medicineLines.take(2)
                    val overflow    = medicineLines.size - visibleMeds.size
                    Row(
                        horizontalArrangement = Arrangement.spacedBy(6.dp),
                        verticalAlignment     = Alignment.CenterVertically,
                        modifier              = Modifier.padding(top = 2.dp)
                    ) {
                        visibleMeds.forEach { med ->
                            MedPill(text = med)
                        }
                        if (overflow > 0) {
                            Text(
                                "+$overflow more",
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.outline
                            )
                        }
                    }

                    // Date
                    Text(
                        text  = dateFormat.format(Date(request.createdAt)),
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.outline,
                        modifier = Modifier.padding(top = 2.dp)
                    )
                }
            }
        }
    }
}

/** Small medicine name chip shown inside list cards. */
@Composable
private fun MedPill(text: String) {
    Surface(
        shape = RoundedCornerShape(6.dp),
        color = MaterialTheme.colorScheme.surfaceVariant
    ) {
        Text(
            text     = text,
            style    = MaterialTheme.typography.labelSmall,
            color    = MaterialTheme.colorScheme.onSurfaceVariant,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
            modifier = Modifier.padding(horizontal = 8.dp, vertical = 3.dp)
        )
    }
}

// ══════════════════════════════════════════════════════════════════════════════
// ── HOME SCREEN  (New Request)
// ══════════════════════════════════════════════════════════════════════════════

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun HomeScreen(
    onSave    : (String, String, String, Boolean) -> Unit,
    onBack    : () -> Unit,
    bottomBar : @Composable () -> Unit = {}
) {
    var name          by remember { mutableStateOf("") }
    var phone         by remember { mutableStateOf("") }
    var medicine      by remember { mutableStateOf("") }
    var isEmergency   by remember { mutableStateOf(false) }
    var phoneError    by remember { mutableStateOf("") }

    val phoneFocusRequester = remember { FocusRequester() }
    val keyboardController = LocalSoftwareKeyboardController.current

    LaunchedEffect(Unit) {
        phoneFocusRequester.requestFocus()
        keyboardController?.show()
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("New Request", fontWeight = FontWeight.SemiBold) },
                navigationIcon = {
                    IconButton(onClick = onBack) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back")
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor          = TopBarContainer,
                    titleContentColor       = TopBarContent,
                    navigationIconContentColor = TopBarContent
                )
            )
        },
        bottomBar = bottomBar
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
        ) {
            // ── Scrollable form content ─────────────────────────────────
            Column(
                modifier = Modifier
                    .weight(1f)
                    .verticalScroll(rememberScrollState())
                    .padding(horizontal = 16.dp, vertical = 16.dp),
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {

                // ── Customer card ────────────────────────────────────────────
                FormCard {
                    SectionLabel("", "Customer Details", "Who is this request for?")
                    Spacer(Modifier.height(14.dp))
                    OutlinedTextField(
                        value         = name,
                        onValueChange = { name = it },
                        label         = { Text("Customer Name (optional)") },
                        leadingIcon   = {
                            Icon(Icons.Filled.Person, null,
                                tint     = MaterialTheme.colorScheme.onSurfaceVariant,
                                modifier = Modifier.size(20.dp))
                        },
                        modifier   = Modifier.fillMaxWidth(),
                        singleLine = true,
                        shape      = RoundedCornerShape(12.dp)
                    )
                    Spacer(Modifier.height(12.dp))
                    OutlinedTextField(
                        value         = phone,
                        onValueChange = { raw ->
                            phone = raw.filter { it.isDigit() }
                            if (phone.isNotEmpty()) phoneError = ""
                        },
                        label       = { Text("Phone Number *") },
                        leadingIcon = {
                            Icon(Icons.Filled.Phone, null,
                                tint     = MaterialTheme.colorScheme.onSurfaceVariant,
                                modifier = Modifier.size(20.dp))
                        },
                        prefix  = {
                            Text("+91  ",
                                style = MaterialTheme.typography.bodyLarge,
                                color = MaterialTheme.colorScheme.onSurfaceVariant)
                        },
                        modifier        = Modifier.fillMaxWidth().focusRequester(phoneFocusRequester),
                        singleLine      = true,
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Phone),
                        isError         = phoneError.isNotEmpty(),
                        supportingText  = {
                            Text(
                                if (phoneError.isNotEmpty()) phoneError else "10-digit mobile number",
                                color = if (phoneError.isNotEmpty()) MaterialTheme.colorScheme.error
                                else MaterialTheme.colorScheme.outline
                            )
                        },
                        shape = RoundedCornerShape(12.dp)
                    )
                }

                // ── Medicine card ────────────────────────────────────────────
                FormCard {
                    SectionLabel("", "Medicines (optional)", "List what the customer needs")
                    Spacer(Modifier.height(14.dp))
                    OutlinedTextField(
                        value         = medicine,
                        onValueChange = { medicine = it },
                        label         = { Text("Medicines") },
                        placeholder   = { Text("e.g.\nParacetamol 500mg\nAmoxicillin 250mg") },
                        modifier      = Modifier
                            .fillMaxWidth()
                            .heightIn(min = 100.dp),
                        minLines        = 3,
                        maxLines        = 6,
                        singleLine      = false,
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Text),
                        supportingText  = {
                            Text(
                                "One medicine per line",
                                color = MaterialTheme.colorScheme.outline
                            )
                        },
                        shape = RoundedCornerShape(12.dp)
                    )
                }

                // ── Emergency toggle ──────────────────────────────────────
                EmergencyToggleChip(
                    isEmergency = isEmergency,
                    onToggle    = { isEmergency = !isEmergency }
                )
            }

            // ── Fixed bottom actions (always visible, no scroll needed) ──
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(MaterialTheme.colorScheme.background)
                    .padding(horizontal = 16.dp, vertical = 10.dp),
                verticalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                Button(
                    onClick = {
                        phoneError = ""
                        when {
                            phone.isBlank()   -> phoneError = "Phone number is required"
                            phone.length < 10 -> phoneError = "Enter a valid 10-digit number"
                            else              -> onSave(name, phone, medicine, isEmergency)
                        }
                    },
                    modifier = Modifier.fillMaxWidth().height(48.dp),
                    shape    = RoundedCornerShape(14.dp)
                ) {
                    Icon(Icons.Filled.Check, null, modifier = Modifier.size(18.dp))
                    Spacer(Modifier.width(8.dp))
                    Text("Save Request", fontWeight = FontWeight.SemiBold)
                }
                TextButton(onClick = onBack, modifier = Modifier.fillMaxWidth()) {
                    Text("Cancel")
                }
            }
        }
    }
}

/** White elevated card wrapper for form sections. */
@Composable
private fun FormCard(content: @Composable ColumnScope.() -> Unit) {
    ElevatedCard(
        modifier  = Modifier.fillMaxWidth(),
        shape     = RoundedCornerShape(18.dp),
        elevation = CardDefaults.elevatedCardElevation(defaultElevation = 1.dp),
        colors    = CardDefaults.elevatedCardColors(
            containerColor = MaterialTheme.colorScheme.surface
        )
    ) {
        Column(modifier = Modifier.padding(20.dp), content = content)
    }
}

// ══════════════════════════════════════════════════════════════════════════════
// ── REQUEST DETAIL SCREEN
// ══════════════════════════════════════════════════════════════════════════════

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RequestDetailScreen(
    request       : RequestEntity,
    isEmergency   : Boolean = false,
    settingsPrefs : SettingsPrefs,
    onEdit        : () -> Unit,
    onDelivered   : () -> Unit,
    onDelete      : () -> Unit,
    onBack        : () -> Unit,
    bottomBar     : @Composable () -> Unit = {}
) {
    val context         = LocalContext.current
    var showContactSheet by remember { mutableStateOf(false) }
    val dateFormat      = remember { SimpleDateFormat("dd MMM yyyy, hh:mm a", Locale.getDefault()) }
    val displayName     = request.customerName.ifBlank { "Unknown Customer" }
    val isPending       = request.status == RequestStatus.PENDING

    val medicineLines = remember(request.medicineName) {
        request.medicineName.lines().filter { it.isNotBlank() }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Request Detail", fontWeight = FontWeight.SemiBold) },
                navigationIcon = {
                    IconButton(onClick = onBack) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back")
                    }
                },
                actions = {
                    IconButton(onClick = onEdit) {
                        Icon(Icons.Filled.Edit, "Edit", modifier = Modifier.size(20.dp))
                    }
                    IconButton(onClick = onDelete) {
                        Icon(Icons.Filled.Delete, "Delete",
                            tint = TopBarContent.copy(alpha = 0.65f),
                            modifier = Modifier.size(20.dp))
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor          = TopBarContainer,
                    titleContentColor       = TopBarContent,
                    navigationIconContentColor = TopBarContent,
                    actionIconContentColor  = TopBarContent
                )
            )
        },
        bottomBar = bottomBar
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .verticalScroll(rememberScrollState())
                .padding(horizontal = 16.dp, vertical = 16.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {

            // ── Hero card ────────────────────────────────────────────────
            val heroBg = if (isEmergency) CardEmergencyBg else if (isPending) CardPendingBg else CardDeliveredBg
            Card(
                modifier  = Modifier.fillMaxWidth(),
                shape     = RoundedCornerShape(20.dp),
                colors    = CardDefaults.cardColors(containerColor = heroBg),
                elevation = CardDefaults.cardElevation(defaultElevation = 1.dp)
            ) {
                Column(modifier = Modifier.padding(20.dp)) {
                    Row(
                        verticalAlignment     = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(14.dp)
                    ) {
                        InitialsAvatar(name = displayName, size = 52)
                        Column(modifier = Modifier.weight(1f)) {
                            Text(
                                text  = displayName,
                                style = MaterialTheme.typography.titleLarge.copy(fontWeight = FontWeight.Bold),
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis
                            )
                            Spacer(Modifier.height(4.dp))
                            Row(
                                verticalAlignment     = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(6.dp)
                            ) {
                                Icon(Icons.Filled.Phone, null,
                                    modifier = Modifier.size(14.dp),
                                    tint     = MaterialTheme.colorScheme.primary)
                                Text(
                                    text  = "+91 ${request.phoneNumber}",
                                    style = MaterialTheme.typography.bodyMedium,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                )
                            }
                        }
                        Column(
                            horizontalAlignment = Alignment.End,
                            verticalArrangement = Arrangement.spacedBy(6.dp)
                        ) {
                            StatusBadge(status = request.status)
                            if (isEmergency) EmergencyBadge()
                        }
                    }

                    HorizontalDivider(
                        modifier  = Modifier.padding(vertical = 14.dp),
                        thickness = 0.5.dp,
                        color     = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f)
                    )

                    Row(
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalAlignment     = Alignment.CenterVertically
                    ) {
                        Icon(Icons.Filled.DateRange, null,
                            modifier = Modifier.size(14.dp),
                            tint     = MaterialTheme.colorScheme.outline)
                        Text(
                            text  = dateFormat.format(Date(request.createdAt)),
                            style = MaterialTheme.typography.labelMedium,
                            color = MaterialTheme.colorScheme.outline
                        )
                    }
                }
            }

            // ── Medicines card ────────────────────────────────────────────
            ElevatedCard(
                modifier  = Modifier.fillMaxWidth(),
                shape     = RoundedCornerShape(18.dp),
                elevation = CardDefaults.elevatedCardElevation(defaultElevation = 1.dp),
                colors    = CardDefaults.elevatedCardColors(
                    containerColor = MaterialTheme.colorScheme.surface
                )
            ) {
                Column(modifier = Modifier.padding(20.dp)) {
                    SectionLabel("", "Medicines", "${medicineLines.size} item${if (medicineLines.size != 1) "s" else ""}")
                    Spacer(Modifier.height(14.dp))
                    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                        medicineLines.forEachIndexed { index, med ->
                            Row(
                                verticalAlignment     = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(12.dp),
                                modifier              = Modifier
                                    .fillMaxWidth()
                                    .clip(RoundedCornerShape(10.dp))
                                    .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f))
                                    .padding(horizontal = 14.dp, vertical = 10.dp)
                            ) {
                                Box(
                                    contentAlignment = Alignment.Center,
                                    modifier = Modifier
                                        .size(24.dp)
                                        .clip(CircleShape)
                                        .background(MaterialTheme.colorScheme.primaryContainer)
                                ) {
                                    Text(
                                        text      = "${index + 1}",
                                        fontSize  = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        color     = MaterialTheme.colorScheme.onPrimaryContainer
                                    )
                                }
                                Text(
                                    text  = med,
                                    style = MaterialTheme.typography.bodyMedium,
                                    color = MaterialTheme.colorScheme.onSurface
                                )
                            }
                        }
                    }
                }
            }

            // ── Action buttons ────────────────────────────────────────────
            Spacer(Modifier.height(2.dp))
            Row(
                modifier              = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                OutlinedButton(
                    onClick  = { showContactSheet = true },
                    modifier = Modifier.weight(1f).height(50.dp),
                    shape    = RoundedCornerShape(14.dp),
                    border   = ButtonDefaults.outlinedButtonBorder(enabled = true)
                ) {
                    Icon(Icons.AutoMirrored.Filled.Send, null, modifier = Modifier.size(16.dp))
                    Spacer(Modifier.width(8.dp))
                    Text("Contact", fontWeight = FontWeight.SemiBold)
                }
                if (isPending) {
                    Button(
                        onClick  = onDelivered,
                        modifier = Modifier.weight(1f).height(50.dp),
                        shape    = RoundedCornerShape(14.dp),
                        colors   = ButtonDefaults.buttonColors(
                            containerColor = StatusDeliveredBg,
                            contentColor   = StatusDeliveredContent
                        )
                    ) {
                        Icon(Icons.Filled.Check, null, modifier = Modifier.size(16.dp))
                        Spacer(Modifier.width(8.dp))
                        Text("Mark Delivered", fontWeight = FontWeight.SemiBold)
                    }
                }
            }
        }
    }

    // ── Contact sheet ─────────────────────────────────────────────────────
    if (showContactSheet) {
        ContactActionSheet(
            onDismiss = { showContactSheet = false },
            onAction  = { action ->
                showContactSheet = false
                val message = buildMessage(settingsPrefs.read(), action)
                val result  = launchContactAction(context, action, request.phoneNumber, message)
                val toast   = when (result) {
                    ContactActionResult.Success              -> null
                    ContactActionResult.InvalidPhone         -> "Invalid phone number"
                    ContactActionResult.WhatsAppNotInstalled -> "WhatsApp not installed"
                    ContactActionResult.NoHandler            -> "No app found to handle this action"
                }
                toast?.let { Toast.makeText(context, it, Toast.LENGTH_SHORT).show() }
            }
        )
    }
}

// ══════════════════════════════════════════════════════════════════════════════
// ── CONTACT ACTION SHEET
// ══════════════════════════════════════════════════════════════════════════════

@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun ContactActionSheet(
    onDismiss : () -> Unit,
    onAction  : (ContactAction) -> Unit
) {
    ModalBottomSheet(
        onDismissRequest = onDismiss,
        shape            = RoundedCornerShape(topStart = 20.dp, topEnd = 20.dp)
    ) {
        Column(modifier = Modifier.padding(bottom = 28.dp)) {
            Text(
                text     = "Contact customer via",
                style    = MaterialTheme.typography.titleSmall.copy(fontWeight = FontWeight.SemiBold),
                color    = MaterialTheme.colorScheme.onSurface,
                modifier = Modifier.padding(horizontal = 24.dp, vertical = 12.dp)
            )
            HorizontalDivider(thickness = 0.5.dp, color = MaterialTheme.colorScheme.outlineVariant)
            Spacer(Modifier.height(8.dp))

            data class ActionItem(val label: String, val sub: String, val icon: @Composable () -> Unit, val action: ContactAction)
            val items = listOf(
                ActionItem("WhatsApp", "Send a WhatsApp message",
                    { Icon(Icons.AutoMirrored.Filled.Send, null, tint = Color(0xFF25D366)) }, ContactAction.WHATSAPP),
                ActionItem("SMS", "Send a text message",
                    { Icon(Icons.AutoMirrored.Filled.Send, null, tint = MaterialTheme.colorScheme.secondary) }, ContactAction.SMS),
                ActionItem("Call", "Place a phone call",
                    { Icon(Icons.Filled.Phone, null, tint = MaterialTheme.colorScheme.tertiary) }, ContactAction.CALL)
            )
            items.forEach { item ->
                ListItem(
                    headlineContent    = { Text(item.label, fontWeight = FontWeight.Medium) },
                    supportingContent  = { Text(item.sub, style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.outline) },
                    leadingContent     = item.icon,
                    trailingContent    = { Icon(Icons.AutoMirrored.Filled.KeyboardArrowRight, null, tint = MaterialTheme.colorScheme.outline, modifier = Modifier.size(18.dp)) },
                    modifier           = Modifier.clickable { onAction(item.action) }
                )
            }
        }
    }
}

// ══════════════════════════════════════════════════════════════════════════════
// ── EDIT REQUEST SCREEN
// ══════════════════════════════════════════════════════════════════════════════

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun EditRequestScreen(
    request     : RequestEntity,
    isEmergency : Boolean = false,
    onSave      : (String, String, String, Boolean) -> Unit,
    onBack      : () -> Unit,
    bottomBar   : @Composable () -> Unit = {}
) {
    var name          by remember { mutableStateOf(request.customerName) }
    var phone         by remember { mutableStateOf(request.phoneNumber) }
    var medicine      by remember { mutableStateOf(request.medicineName) }
    var emergency     by remember { mutableStateOf(isEmergency) }
    var phoneError    by remember { mutableStateOf("") }

    Scaffold(
        topBar = {
            TopAppBar(
                title = {
                    Column {
                        Text("Edit Request", fontWeight = FontWeight.SemiBold)
                        Text(
                            request.customerName.ifBlank { "Request #${request.id}" },
                            style = MaterialTheme.typography.labelSmall,
                            color = TopBarContent.copy(alpha = 0.65f)
                        )
                    }
                },
                navigationIcon = {
                    IconButton(onClick = onBack) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back")
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor          = TopBarContainer,
                    titleContentColor       = TopBarContent,
                    navigationIconContentColor = TopBarContent
                )
            )
        },
        bottomBar = bottomBar
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
        ) {
            // ── Scrollable form content ─────────────────────────────────
            Column(
                modifier = Modifier
                    .weight(1f)
                    .verticalScroll(rememberScrollState())
                    .padding(horizontal = 16.dp, vertical = 16.dp),
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {

                // ── Info banner ───────────────────────────────────────────────
                Surface(
                    modifier = Modifier.fillMaxWidth(),
                    shape    = RoundedCornerShape(14.dp),
                    color    = MaterialTheme.colorScheme.tertiaryContainer.copy(alpha = 0.4f)
                ) {
                    Row(
                        modifier              = Modifier.padding(14.dp),
                        verticalAlignment     = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        Text("✏️", fontSize = 18.sp)
                        Text(
                            "Update customer or medicine details below.",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurface
                        )
                    }
                }

                // ── Customer card ─────────────────────────────────────────────
                FormCard {
                    SectionLabel("", "Customer Details", "Who is this request for?")
                    Spacer(Modifier.height(14.dp))
                    OutlinedTextField(
                        value = name, onValueChange = { name = it },
                        label       = { Text("Customer Name (optional)") },
                        leadingIcon = { Icon(Icons.Filled.Person, null, tint = MaterialTheme.colorScheme.onSurfaceVariant, modifier = Modifier.size(20.dp)) },
                        modifier    = Modifier.fillMaxWidth(), singleLine = true,
                        shape       = RoundedCornerShape(12.dp)
                    )
                    Spacer(Modifier.height(12.dp))
                    OutlinedTextField(
                        value         = phone,
                        onValueChange = { raw ->
                            phone = raw.filter { it.isDigit() }
                            if (phone.isNotEmpty()) phoneError = ""
                        },
                        label       = { Text("Phone Number *") },
                        leadingIcon = { Icon(Icons.Filled.Phone, null, tint = MaterialTheme.colorScheme.onSurfaceVariant, modifier = Modifier.size(20.dp)) },
                        prefix      = { Text("+91  ", style = MaterialTheme.typography.bodyLarge, color = MaterialTheme.colorScheme.onSurfaceVariant) },
                        modifier        = Modifier.fillMaxWidth(), singleLine = true,
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Phone),
                        isError         = phoneError.isNotEmpty(),
                        supportingText  = {
                            Text(if (phoneError.isNotEmpty()) phoneError else "10-digit mobile number",
                                color = if (phoneError.isNotEmpty()) MaterialTheme.colorScheme.error else MaterialTheme.colorScheme.outline)
                        },
                        shape = RoundedCornerShape(12.dp)
                    )
                }

                // ── Medicine card ─────────────────────────────────────────────
                FormCard {
                    SectionLabel("", "Medicines (optional)", "List what the customer needs")
                    Spacer(Modifier.height(14.dp))
                    OutlinedTextField(
                        value         = medicine,
                        onValueChange = { medicine = it },
                        label         = { Text("Medicines") },
                        placeholder   = { Text("e.g.\nParacetamol 500mg\nAmoxicillin 250mg") },
                        modifier      = Modifier.fillMaxWidth().heightIn(min = 100.dp),
                        minLines      = 3, maxLines = 6, singleLine = false,
                        supportingText = {
                            Text("One medicine per line",
                                color = MaterialTheme.colorScheme.outline)
                        },
                        shape = RoundedCornerShape(12.dp)
                    )
                }

                // ── Emergency toggle ────────────────────────────────────────
                EmergencyToggleChip(
                    isEmergency = emergency,
                    onToggle    = { emergency = !emergency }
                )
            }

            // ── Fixed bottom actions (always visible, no scroll needed) ──
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(MaterialTheme.colorScheme.background)
                    .padding(horizontal = 16.dp, vertical = 10.dp),
                verticalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                Button(
                    onClick = {
                        phoneError = ""
                        when {
                            phone.isBlank()    -> phoneError = "Phone number is required"
                            phone.length < 10  -> phoneError = "Enter a valid 10-digit number"
                            else               -> onSave(name, phone, medicine, emergency)
                        }
                    },
                    modifier = Modifier.fillMaxWidth().height(48.dp),
                    shape    = RoundedCornerShape(14.dp)
                ) {
                    Icon(Icons.Filled.Check, null, modifier = Modifier.size(18.dp))
                    Spacer(Modifier.width(8.dp))
                    Text("Save Changes", fontWeight = FontWeight.SemiBold)
                }
                TextButton(onClick = onBack, modifier = Modifier.fillMaxWidth()) {
                    Text("Cancel")
                }
            }
        }
    }
}

// ══════════════════════════════════════════════════════════════════════════════
// ── SETTINGS SCREEN
// ══════════════════════════════════════════════════════════════════════════════

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun SettingsScreen(
    settingsPrefs : SettingsPrefs,
    onBack        : () -> Unit,
    bottomBar     : @Composable () -> Unit = {}
) {
    val context          = LocalContext.current
    val current          = remember { settingsPrefs.read() }
    var shopName         by remember { mutableStateOf(current.shopName) }
    var shopAddress      by remember { mutableStateOf(current.shopAddress) }
    var contact1Name     by remember { mutableStateOf(current.contact1Name) }
    var contact1Phone    by remember { mutableStateOf(current.contact1Phone) }
    var contact2Name     by remember { mutableStateOf(current.contact2Name) }
    var contact2Phone    by remember { mutableStateOf(current.contact2Phone) }

    val previewMessage = remember(shopName, shopAddress, contact1Name, contact1Phone, contact2Name, contact2Phone) {
        buildMessage(AppSettings(shopName, shopAddress, contact1Name, contact1Phone, contact2Name, contact2Phone))
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Settings", fontWeight = FontWeight.SemiBold) },
                navigationIcon = {
                    IconButton(onClick = onBack) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back")
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor          = TopBarContainer,
                    titleContentColor       = TopBarContent,
                    navigationIconContentColor = TopBarContent
                )
            )
        },
        bottomBar = bottomBar
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .verticalScroll(rememberScrollState())
                .padding(horizontal = 16.dp, vertical = 16.dp),
            verticalArrangement = Arrangement.spacedBy(20.dp)
        ) {

            // ── Info banner ───────────────────────────────────────────────
            Surface(
                modifier = Modifier.fillMaxWidth(),
                shape    = RoundedCornerShape(14.dp),
                color    = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.35f)
            ) {
                Row(
                    modifier              = Modifier.padding(14.dp),
                    verticalAlignment     = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    Text("⚙️", fontSize = 18.sp)
                    Text(
                        "These details appear in every message sent to your customers.",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurface
                    )
                }
            }

            // ── Shop card ─────────────────────────────────────────────────
            FormCard {
                SectionLabel("", "Shop Information", "Your pharmacy / store name")
                Spacer(Modifier.height(14.dp))
                OutlinedTextField(
                    value = shopName, onValueChange = { shopName = it },
                    label       = { Text("Shop Name") },
                    leadingIcon = { Icon(Icons.Filled.Home, null, tint = MaterialTheme.colorScheme.onSurfaceVariant, modifier = Modifier.size(20.dp)) },
                    modifier    = Modifier.fillMaxWidth(), singleLine = true,
                    shape       = RoundedCornerShape(12.dp)
                )
                Spacer(Modifier.height(12.dp))
                OutlinedTextField(
                    value = shopAddress, onValueChange = { shopAddress = it },
                    label       = { Text("Shop Address") },
                    placeholder = { Text("e.g. Ainapur") },
                    leadingIcon = { Icon(Icons.Filled.LocationOn, null, tint = MaterialTheme.colorScheme.onSurfaceVariant, modifier = Modifier.size(20.dp)) },
                    modifier    = Modifier.fillMaxWidth(), singleLine = true,
                    shape       = RoundedCornerShape(12.dp)
                )
            }

            // ── Contact 1 card ────────────────────────────────────────────
            FormCard {
                SectionLabel("", "Primary Contact", "First point of contact")
                Spacer(Modifier.height(14.dp))
                OutlinedTextField(
                    value = contact1Name, onValueChange = { contact1Name = it },
                    label = { Text("Name") },
                    leadingIcon = { Icon(Icons.Filled.Person, null, tint = MaterialTheme.colorScheme.onSurfaceVariant, modifier = Modifier.size(20.dp)) },
                    modifier = Modifier.fillMaxWidth(), singleLine = true,
                    shape = RoundedCornerShape(12.dp)
                )
                Spacer(Modifier.height(12.dp))
                OutlinedTextField(
                    value         = contact1Phone,
                    onValueChange = { raw -> contact1Phone = raw.filter { it.isDigit() } },
                    label       = { Text("Phone") },
                    leadingIcon = { Icon(Icons.Filled.Phone, null, tint = MaterialTheme.colorScheme.onSurfaceVariant, modifier = Modifier.size(20.dp)) },
                    prefix      = { Text("+91  ", style = MaterialTheme.typography.bodyLarge, color = MaterialTheme.colorScheme.onSurfaceVariant) },
                    modifier    = Modifier.fillMaxWidth(), singleLine = true,
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Phone),
                    shape = RoundedCornerShape(12.dp)
                )
            }

            // ── Contact 2 card ────────────────────────────────────────────
            FormCard {
                SectionLabel("", "Secondary Contact", "Optional additional contact")
                Spacer(Modifier.height(14.dp))
                OutlinedTextField(
                    value = contact2Name, onValueChange = { contact2Name = it },
                    label = { Text("Name") },
                    leadingIcon = { Icon(Icons.Filled.Person, null, tint = MaterialTheme.colorScheme.onSurfaceVariant, modifier = Modifier.size(20.dp)) },
                    modifier = Modifier.fillMaxWidth(), singleLine = true,
                    shape = RoundedCornerShape(12.dp)
                )
                Spacer(Modifier.height(12.dp))
                OutlinedTextField(
                    value         = contact2Phone,
                    onValueChange = { raw -> contact2Phone = raw.filter { it.isDigit() } },
                    label       = { Text("Phone") },
                    leadingIcon = { Icon(Icons.Filled.Phone, null, tint = MaterialTheme.colorScheme.onSurfaceVariant, modifier = Modifier.size(20.dp)) },
                    prefix      = { Text("+91  ", style = MaterialTheme.typography.bodyLarge, color = MaterialTheme.colorScheme.onSurfaceVariant) },
                    modifier    = Modifier.fillMaxWidth(), singleLine = true,
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Phone),
                    shape = RoundedCornerShape(12.dp)
                )
            }

            // ── Message preview card ──────────────────────────────────────
            ElevatedCard(
                modifier  = Modifier.fillMaxWidth(),
                shape     = RoundedCornerShape(18.dp),
                elevation = CardDefaults.elevatedCardElevation(defaultElevation = 2.dp),
                colors    = CardDefaults.elevatedCardColors(
                    containerColor = MaterialTheme.colorScheme.surface
                )
            ) {
                Column(modifier = Modifier.padding(20.dp)) {
                    // Header row with icon
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        Box(
                            contentAlignment = Alignment.Center,
                            modifier = Modifier
                                .size(36.dp)
                                .clip(RoundedCornerShape(10.dp))
                                .background(Color(0xFF25D366).copy(alpha = 0.15f))
                        ) {
                            Text("", fontSize = 16.sp)
                        }
                        Column(modifier = Modifier.weight(1f)) {
                            Text(
                                "Message Preview",
                                style = MaterialTheme.typography.titleSmall.copy(fontWeight = FontWeight.SemiBold),
                                color = MaterialTheme.colorScheme.onSurface
                            )
                            Text(
                                "How customers will see your message",
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.outline
                            )
                        }
                        // WhatsApp badge
                        Surface(
                            shape = RoundedCornerShape(8.dp),
                            color = Color(0xFF25D366).copy(alpha = 0.12f)
                        ) {
                            Text(
                                "WhatsApp",
                                modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp),
                                style = MaterialTheme.typography.labelSmall.copy(
                                    fontWeight = FontWeight.SemiBold,
                                    color = Color(0xFF25D366)
                                )
                            )
                        }
                    }

                    Spacer(Modifier.height(16.dp))
                    HorizontalDivider(
                        thickness = 0.5.dp,
                        color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f)
                    )
                    Spacer(Modifier.height(16.dp))

                    // Chat bubble background
                    Box(modifier = Modifier.fillMaxWidth()) {
                        Surface(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(start = 4.dp),
                            shape = RoundedCornerShape(
                                topStart = 4.dp,
                                topEnd = 16.dp,
                                bottomStart = 16.dp,
                                bottomEnd = 16.dp
                            ),
                            color = Color(0xFFDCF8C6),
                            shadowElevation = 0.5.dp
                        ) {
                            Column(modifier = Modifier.padding(14.dp)) {
                                Text(
                                    text     = previewMessage,
                                    style    = MaterialTheme.typography.bodySmall.copy(
                                        lineHeight = 18.sp,
                                        color = Color(0xFF1B1B1B)
                                    )
                                )
                                Spacer(Modifier.height(6.dp))
                                // Timestamp row
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.End,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text(
                                        text = "Preview",
                                        style = MaterialTheme.typography.labelSmall.copy(
                                            fontSize = 10.sp,
                                            color = Color(0xFF6B8F71)
                                        )
                                    )
                                    Spacer(Modifier.width(4.dp))
                                    Text("✓✓", fontSize = 10.sp, color = Color(0xFF53BDEB))
                                }
                            }
                        }
                    }
                }
            }

            // ── Save button ───────────────────────────────────────────────
            Spacer(Modifier.height(4.dp))
            Button(
                onClick = {
                    settingsPrefs.save(AppSettings(shopName, shopAddress, contact1Name, contact1Phone, contact2Name, contact2Phone))
                    Toast.makeText(context, "Settings saved", Toast.LENGTH_SHORT).show()
                    onBack()
                },
                modifier = Modifier.fillMaxWidth().height(52.dp),
                shape    = RoundedCornerShape(14.dp)
            ) {
                Icon(Icons.Filled.Check, null, modifier = Modifier.size(18.dp))
                Spacer(Modifier.width(8.dp))
                Text("Save Settings", fontWeight = FontWeight.SemiBold)
            }
            Spacer(Modifier.height(16.dp))
        }
    }
}

.?package com.niranjan.medqueue.autosend

import android.accessibilityservice.AccessibilityService
import android.content.Intent
import android.os.Handler
import android.os.Looper
import android.util.Log
import android.view.accessibility.AccessibilityEvent
import android.view.accessibility.AccessibilityNodeInfo
import com.niranjan.medqueue.MainActivity

/**
 * Accessibility service that auto-taps the **Send** button inside WhatsApp
 * when [AutoSendPrefs.isAutoSendPending] is true.
 *
 * Safety guarantees:
 * - Only listens to `com.whatsapp` (declared in XML config).
 * - Only acts when **both** user-toggle AND per-action flag are set.
 * - Clears the pending flag immediately after tapping, so it never
 *   fires twice or interferes with normal WhatsApp usage.
 * - Returns the user to MedQueue after sending.
 */
class WhatsAppAutoSendService : AccessibilityService() {

    companion object {
        private const val TAG = "WA_AutoSend"

        /** Content description WhatsApp uses for the send button. */
        private const val SEND_DESC = "Send"

        /** Delay (ms) before navigating back to MedQueue after send. */
        private const val RETURN_DELAY_MS = 1000L

        /** Max attempts to look for the send button before giving up. */
        private const val MAX_RETRIES = 15

        /** Debounce window – ignore rapid duplicate events. */
        private const val DEBOUNCE_MS = 400L
    }

    private val handler = Handler(Looper.getMainLooper())

    /** Prevents re-entrance while we're already processing. */
    @Volatile private var processing = false

    /** Retry counter – reset every time a new pending flag is set. */
    private var retryCount = 0

    /** Timestamp of last event we actually processed. */
    private var lastProcessedAt = 0L

    // ─────────────────────────────────────────────────────────────────────────

    override fun onAccessibilityEvent(event: AccessibilityEvent?) {
        if (event == null) return
        if (processing) return
        if (!AutoSendPrefs.isAutoSendEnabled(this)) return
        if (!AutoSendPrefs.isAutoSendPending(this)) return

        // Debounce: skip events that arrive too quickly
        val now = System.currentTimeMillis()
        if (now - lastProcessedAt < DEBOUNCE_MS) return
        lastProcessedAt = now

        val root = rootInActiveWindow ?: return

        try {
            val sendNode = findSendButton(root)
            if (sendNode != null) {
                processing = true
                retryCount = 0
                Log.d(TAG, "Found Send button – clicking")

                sendNode.performAction(AccessibilityNodeInfo.ACTION_CLICK)
                AutoSendPrefs.clearAutoSendPending(this)

                // Give WhatsApp a moment to process the send, then return
                handler.postDelayed({
                    returnToMedQueue()
                    processing = false
                }, RETURN_DELAY_MS)
            } else {
                retryCount++
                if (retryCount >= MAX_RETRIES) {
                    Log.w(TAG, "Send button not found after $MAX_RETRIES retries – giving up")
                    AutoSendPrefs.clearAutoSendPending(this)
                    retryCount = 0
                }
            }
        } finally {
            root.recycle()
        }
    }

    override fun onInterrupt() {
        Log.w(TAG, "Service interrupted")
        processing = false
    }

    // ── Helpers ──────────────────────────────────────────────────────────────

    /**
     * Recursively searches the node tree for a clickable node whose
     * content-description equals "Send" (case-insensitive).
     */
    private fun findSendButton(root: AccessibilityNodeInfo): AccessibilityNodeInfo? {
        // Fast path – search by content description text
        val candidates = root.findAccessibilityNodeInfosByText(SEND_DESC)
        for (node in candidates) {
            val desc = node.contentDescription?.toString() ?: continue
            if (desc.equals(SEND_DESC, ignoreCase = true) && node.isClickable) {
                return node
            }
        }

        // Slow path – full tree traversal as fallback
        return walkTree(root)
    }

    private fun walkTree(node: AccessibilityNodeInfo): AccessibilityNodeInfo? {
        val desc = node.contentDescription?.toString()
        if (desc != null && desc.equals(SEND_DESC, ignoreCase = true) && node.isClickable) {
            return node
        }
        for (i in 0 until node.childCount) {
            val child = node.getChild(i) ?: continue
            val result = walkTree(child)
            if (result != null) return result
            child.recycle()
        }
        return null
    }

    /** Brings MedQueue back to the foreground. */
    private fun returnToMedQueue() {
        try {
            val intent = Intent(this, MainActivity::class.java).apply {
                flags = Intent.FLAG_ACTIVITY_NEW_TASK or
                        Intent.FLAG_ACTIVITY_CLEAR_TOP or
                        Intent.FLAG_ACTIVITY_SINGLE_TOP
            }
            startActivity(intent)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to return to MedQueue", e)
        }
    }
}

package com.niranjan.medqueue.autosend

import android.accessibilityservice.AccessibilityService
import android.content.Intent
import android.os.Handler
import android.os.Looper
import android.util.Log
import android.view.accessibility.AccessibilityEvent
import android.view.accessibility.AccessibilityNodeInfo
import com.niranjan.medqueue.MainActivity

/**
 * Accessibility service that auto-taps the **Send** button inside WhatsApp
 * when [AutoSendPrefs.isAutoSendPending] is true.
 *
 * Safety guarantees:
 * - Only listens to `com.whatsapp` (declared in XML config).
 * - Only acts when **both** user-toggle AND per-action flag are set.
 * - Clears the pending flag immediately after tapping, so it never
 *   fires twice or interferes with normal WhatsApp usage.
 * - Returns the user to MedQueue after sending.
 */
class WhatsAppAutoSendService : AccessibilityService() {

    companion object {
        private const val TAG = "WA_AutoSend"

        /** Content description WhatsApp uses for the send button. */
        private const val SEND_DESC = "Send"

        /** Delay (ms) before navigating back to MedQueue after send. */
        private const val RETURN_DELAY_MS = 1000L

        /** Max attempts to look for the send button before giving up. */
        private const val MAX_RETRIES = 15

        /** Debounce window – ignore rapid duplicate events. */
        private const val DEBOUNCE_MS = 400L
    }

    private val handler = Handler(Looper.getMainLooper())

    /** Prevents re-entrance while we're already processing. */
    @Volatile private var processing = false

    /** Retry counter – reset every time a new pending flag is set. */
    private var retryCount = 0

    /** Timestamp of last event we actually processed. */
    private var lastProcessedAt = 0L

    // ─────────────────────────────────────────────────────────────────────────

    override fun onAccessibilityEvent(event: AccessibilityEvent?) {
        if (event == null) return
        if (processing) return
        if (!AutoSendPrefs.isAutoSendEnabled(this)) return
        if (!AutoSendPrefs.isAutoSendPending(this)) return

        // Debounce: skip events that arrive too quickly
        val now = System.currentTimeMillis()
        if (now - lastProcessedAt < DEBOUNCE_MS) return
        lastProcessedAt = now

        val root = rootInActiveWindow ?: return

        try {
            val sendNode = findSendButton(root)
            if (sendNode != null) {
                processing = true
                retryCount = 0
                Log.d(TAG, "Found Send button – clicking")

                sendNode.performAction(AccessibilityNodeInfo.ACTION_CLICK)
                AutoSendPrefs.clearAutoSendPending(this)

                // Give WhatsApp a moment to process the send, then return
                handler.postDelayed({
                    returnToMedQueue()
                    processing = false
                }, RETURN_DELAY_MS)
            } else {
                retryCount++
                if (retryCount >= MAX_RETRIES) {
                    Log.w(TAG, "Send button not found after $MAX_RETRIES retries – giving up")
                    AutoSendPrefs.clearAutoSendPending(this)
                    retryCount = 0
                }
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error processing event", e)
        }
    }

    override fun onInterrupt() {
        Log.w(TAG, "Service interrupted")
        processing = false
    }

    // ── Helpers ──────────────────────────────────────────────────────────────

    /**
     * Recursively searches the node tree for a clickable node whose
     * content-description equals "Send" (case-insensitive).
     */
    private fun findSendButton(root: AccessibilityNodeInfo): AccessibilityNodeInfo? {
        // Fast path – search by content description text
        val candidates = root.findAccessibilityNodeInfosByText(SEND_DESC)
        for (node in candidates) {
            val desc = node.contentDescription?.toString() ?: continue
            if (desc.equals(SEND_DESC, ignoreCase = true) && node.isClickable) {
                return node
            }
        }

        // Slow path – full tree traversal as fallback
        return walkTree(root)
    }

    private fun walkTree(node: AccessibilityNodeInfo): AccessibilityNodeInfo? {
        val desc = node.contentDescription?.toString()
        if (desc != null && desc.equals(SEND_DESC, ignoreCase = true) && node.isClickable) {
            return node
        }
        for (i in 0 until node.childCount) {
            val child = node.getChild(i) ?: continue
            val result = walkTree(child)
            if (result != null) return result
        }
        return null
    }

    /** Brings MedQueue back to the foreground. */
    private fun returnToMedQueue() {
        try {
            val intent = Intent(this, MainActivity::class.java).apply {
                flags = Intent.FLAG_ACTIVITY_NEW_TASK or
                        Intent.FLAG_ACTIVITY_CLEAR_TOP or
                        Intent.FLAG_ACTIVITY_SINGLE_TOP
            }
            startActivity(intent)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to return to MedQueue", e)
        }
    }
}
